  "implementation": "def solve(case):
    import json
    # Validate case structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'threshold' not in case:
        raise ValueError("missing threshold")
    if 'calls' not in case:
        raise ValueError("missing calls")
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    required_call_fields = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be a dict")
        for field in required_call_fields:
            if field not in call:
                raise ValueError(f"missing field {field} in call")
        call_id = call['call_id']
        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        loss_woc = call['loss_without_call']
        loss_wc = call['loss_with_call']
        if not isinstance(loss_woc, (int, float)) or not isinstance(loss_wc, (int, float)):
            raise ValueError("loss values must be numbers")
        tokens = call['prediction_tokens']
        if not isinstance(tokens, int) or tokens <= 0:
            raise ValueError("prediction_tokens must be a positive integer")
        parseable = call['parseable']
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be boolean")
        gain = loss_woc - loss_wc
        normalized_gain = gain / tokens
        accepted = parseable and normalized_gain >= threshold
        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': normalized_gain
        })
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"
}
